from PIL import Image
import numpy as np, math
im = np.array(Image.open('mol_0055.png').convert('L'))
blk = (im < 128)
H,W = blk.shape
nodes = {
 'A':(255,225),'B':(300,330),'C':(372,260),'D':(475,303),'E':(485,232),
 'F':(605,262),'G':(720,232),'Hc':(660,450),'I':(660,330),'J':(660,152),
 'Ch':(545,485),'Oa':(557,197),'Ob':(600,385),
}
def black(x,y):
    xi=int(round(x)); yi=int(round(y))
    if xi<0 or yi<0 or xi>=W or yi>=H: return False
    return blk[yi,xi]
for name,(nx,ny) in nodes.items():
    hits=[]
    for deg in range(0,360,2):
        th=math.radians(deg)
        dx,dy=math.cos(th),math.sin(th)
        # sample from r=14 to r=40 ; require >=80% black
        cnt=0; tot=0
        for r in np.arange(14,41,1.0):
            tot+=1
            if black(nx+dx*r, ny+dy*r): cnt+=1
        if cnt/tot >= 0.85:
            hits.append(deg)
    # group consecutive angles
    groups=[]
    for d in hits:
        if groups and d-groups[-1][-1]<=4: groups[-1].append(d)
        else: groups.append([d])
    if groups and len(groups)>1 and (groups[0][0]==0 and groups[-1][-1]>=356):
        groups[0]=groups.pop()+groups[0]
    out=[]
    for g in groups:
        out.append(sum(g)/len(g))
    print(name, [round(o) for o in out])
